<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class SupportController extends Controller {
 public function index(Request $r){$status=$r->query('status');abort_unless(!$status||in_array($status,['open','pending','closed'],true),422);$tickets=DB::table('support_tickets')->join('users','users.id','=','support_tickets.user_id')->select('support_tickets.*','users.name as client_name','users.email as client_email')->when($status,fn($q)=>$q->where('support_tickets.status',$status))->latest('support_tickets.last_message_at')->paginate(20)->withQueryString();return view('admin.support.index',compact('tickets'));}
 public function show(int $ticket){$record=DB::table('support_tickets')->join('users','users.id','=','support_tickets.user_id')->select('support_tickets.*','users.name as client_name','users.email as client_email')->where('support_tickets.id',$ticket)->first();abort_unless($record,404);$messages=DB::table('support_messages')->leftJoin('users','users.id','=','support_messages.user_id')->where('support_ticket_id',$record->id)->select('support_messages.*','users.name as sender_name')->orderBy('support_messages.created_at')->get();return view('admin.support.show',['ticket'=>$record,'messages'=>$messages]);}
 public function reply(Request $r,int $ticket){$v=$r->validate(['message'=>['required','string','min:2','max:5000'],'status'=>['required','in:open,pending,closed']]);$record=DB::table('support_tickets')->where('id',$ticket)->first();abort_unless($record,404);DB::transaction(function()use($r,$v,$record){$now=now();DB::table('support_messages')->insert(['support_ticket_id'=>$record->id,'user_id'=>$r->user()->id,'sender_role'=>'admin','message'=>$v['message'],'created_at'=>$now,'updated_at'=>$now]);DB::table('support_tickets')->where('id',$record->id)->update(['status'=>$v['status'],'closed_at'=>$v['status']==='closed'?$now:null,'last_message_at'=>$now,'updated_at'=>$now]);DB::table('user_notifications')->insertOrIgnore(['user_id'=>$record->user_id,'event_key'=>'support-reply:'.$record->id.':'.(string)DB::table('support_messages')->where('support_ticket_id',$record->id)->max('id'),'type'=>'support_reply','title'=>'Support replied to your ticket','body'=>'An administrator replied to support ticket #'.$record->id.'.','data'=>json_encode(['ticket_id'=>$record->id]),'created_at'=>$now,'updated_at'=>$now]);});return redirect()->route('admin.support.show',$record->id)->with('status','Support reply sent.');}
}